const promptBuilder = new PromptBuilder({identity: 'You are HAL.'});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('Database connection failed in beforeSession');
    const observed: {rejection?: unknown; onErrorArg?: Error; afterSessionRan?: boolean} = {};

    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          observed.onErrorArg = error;
        },
        afterSession: async () => {
          observed.afterSessionRan = true;
        },
      },
    });

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (rejection) {
      observed.rejection = rejection;
    }

    expect(observed).toEqual({rejection: errorToThrow, onErrorArg: errorToThrow, afterSessionRan: true});
  });
});

